#import <Cocoa/Cocoa.h>
#import <IOSurface/IOSurface.h>
#import <QuartzCore/QuartzCore.h>
#include <dlfcn.h>
#include <stdio.h>
static double now(void) { static double (*f)(void); if(!f) f=dlsym(RTLD_DEFAULT,"vox_precise_scroll_diagnostic_time"); return f?f():-1; }
static IOSurfaceRef surface(CFDictionaryRef p) { double t=now(); IOSurfaceRef s=IOSurfaceCreate(p); double e=now(); if(t>=0&&t<200000)fprintf(stderr,"TAIL surface t=%.3f us=%.3f\n",t,e-t); return s; }
static CGContextRef bitmap(void*d,size_t w,size_t h,size_t b,size_t p,CGColorSpaceRef c,uint32_t i){ double t=now(); CGContextRef r=CGBitmapContextCreate(d,w,h,b,p,c,i); double e=now(); if(t>=0&&t<200000)fprintf(stderr,"TAIL bitmap t=%.3f us=%.3f\n",t,e-t); return r; }
extern void ladybird_v_skia_set_root_raster_scroll_y(double);
static void scroll(double y){double t=now();if(t>=0&&t<200000)fprintf(stderr,"TAIL replay t=%.3f y=%g\n",t,y);ladybird_v_skia_set_root_raster_scroll_y(y);}
__attribute__((used)) static struct {const void *r,*o;} interposes[] __attribute__((section("__DATA,__interpose")))={{surface,IOSurfaceCreate},{bitmap,CGBitmapContextCreate},{scroll,ladybird_v_skia_set_root_raster_scroll_y}};
